//! End-to-end multi-agent scenarios on disposable repositories.
//!
//! Every test drives the shipped binary exactly as an operator or an external
//! orchestrator would: real Git, real files, real exit codes. Patches are
//! produced by a throw-away Git worktree — the same thing an independent agent
//! would do — and are never generated by Flow itself.
//!
//! The scenarios M1–M6 in `docs/reviews/FLOW-MVP-0.1-VERIFICATION-REPORT.md` name
//! these tests; a skipped test is never a pass.

#[path = "../src/json.rs"]
#[allow(dead_code)]
mod json;

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};

use json::Json;

static COUNTER: AtomicUsize = AtomicUsize::new(0);

struct Repo {
    path: PathBuf,
}

impl Drop for Repo {
    fn drop(&mut self) {
        let _ = remove_tree(&self.path);
    }
}

fn clear_readonly(p: &Path) {
    if let Ok(meta) = fs::symlink_metadata(p) {
        let perms = meta.permissions();
        if perms.readonly() {
            let mut writable = perms.clone();
            #[allow(clippy::permissions_set_readonly_false)]
            writable.set_readonly(false);
            let _ = fs::set_permissions(p, writable);
        }
    }
    if p.is_dir() {
        if let Ok(entries) = fs::read_dir(p) {
            for entry in entries.flatten() {
                clear_readonly(&entry.path());
            }
        }
    }
}

fn remove_tree(path: &Path) -> std::io::Result<()> {
    clear_readonly(path);
    fs::remove_dir_all(path)
}

fn unique_dir(tag: &str) -> PathBuf {
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    std::env::temp_dir().join(format!("flow-mvp-{}-{}-{tag}", std::process::id(), n))
}

fn git(repo: &Path, args: &[&str]) -> String {
    let out = Command::new("git")
        .arg("-C")
        .arg(repo)
        .args(args)
        .output()
        .expect("git runs");
    assert!(
        out.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

/// Raw stdout bytes: a patch must be captured byte for byte (trimming the final
/// newline makes `git apply` reject it as a corrupt patch).
fn git_raw(repo: &Path, args: &[&str]) -> Vec<u8> {
    let out = Command::new("git")
        .arg("-C")
        .arg(repo)
        .args(args)
        .output()
        .expect("git runs");
    assert!(
        out.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    out.stdout
}

fn flow(repo: &Path, args: &[&str]) -> (i32, Json) {
    flow_with_env(repo, args, &[])
}

fn flow_with_env(repo: &Path, args: &[&str], envs: &[(&str, &str)]) -> (i32, Json) {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_flow"));
    cmd.current_dir(repo).args(args);
    for (k, v) in envs {
        cmd.env(k, v);
    }
    let out = cmd.output().expect("flow runs");
    let text = String::from_utf8_lossy(&out.stdout).to_string();
    let parsed = if text.trim().is_empty() {
        Json::Null
    } else {
        json::parse(&text).unwrap_or_else(|e| {
            panic!(
                "flow {args:?} printed non-JSON ({e}):\n{text}\n{}",
                String::from_utf8_lossy(&out.stderr)
            )
        })
    };
    (out.status.code().unwrap_or(-1), parsed)
}

fn status_of(value: &Json) -> String {
    value
        .get("status")
        .and_then(Json::as_str)
        .unwrap_or("<none>")
        .to_string()
}

fn code_of(value: &Json) -> String {
    value
        .get("code")
        .and_then(Json::as_str)
        .unwrap_or("<none>")
        .to_string()
}

fn field(value: &Json, key: &str) -> String {
    value
        .get(key)
        .and_then(Json::as_str)
        .unwrap_or("")
        .to_string()
}

const GREEN: &str =
    r#"{"id":"green","program":"git","args":["--version"],"required":true,"timeout_s":30}"#;

/// Write a policy without approving it, to model a repository that arrives with
/// a `.flow/config.json` (a claim, not a consent).
fn write_config_unapproved(repo: &Path, obligations: &str) {
    let dir = repo.join(".flow");
    fs::create_dir_all(&dir).unwrap();
    fs::write(
        dir.join("config.json"),
        format!(
            r#"{{"schema":"flow-config/1","policy_version":"FLOW-POLICY-1","execution_boundary":"local-trusted","obligations":[{obligations}],"disabled":false}}"#
        ),
    )
    .unwrap();
}

fn write_config(repo: &Path, obligations: &str) {
    let dir = repo.join(".flow");
    fs::create_dir_all(&dir).unwrap();
    fs::write(
        dir.join("config.json"),
        format!(
            r#"{{"schema":"flow-config/1","policy_version":"FLOW-POLICY-1","execution_boundary":"local-trusted","obligations":[{obligations}],"disabled":false}}"#
        ),
    )
    .unwrap();
    let (code, out) = flow(repo, &["approve"]);
    assert_eq!(code, 0, "policy must be adoptable: {out}");
}

/// A disposable repository with a seeded base commit and an adopted policy.
fn new_repo() -> (Repo, String) {
    let path = unique_dir("repo");
    let _ = remove_tree(&path);
    fs::create_dir_all(&path).expect("temp dir");
    git(&path, &["init", "-q", "-b", "main"]);
    git(&path, &["config", "user.name", "Flow MVP Test"]);
    git(&path, &["config", "user.email", "flow@example.invalid"]);
    git(&path, &["config", "commit.gpgsign", "false"]);
    fs::write(path.join("alpha.txt"), "one\ntwo\nthree\n").unwrap();
    fs::write(path.join("shared.txt"), "red\ngreen\nblue\n").unwrap();
    git(&path, &["add", "-A"]);
    git(&path, &["commit", "-q", "-m", "base"]);
    let base = git(&path, &["rev-parse", "HEAD"]);
    let (code, out) = flow(&path, &["init"]);
    assert_eq!(code, 0, "flow init: {out}");
    write_config(&path, GREEN);
    (Repo { path }, base)
}

/// Write `content` into the throw-away worktree, then read it back as a binary
/// patch against `base`. `content = None` deletes the path.
fn make_patch(
    repo: &Path,
    base: &str,
    edits: &[(&str, Option<&str>)],
    executable: bool,
) -> PathBuf {
    let work = unique_dir("agent");
    let _ = remove_tree(&work);
    git(
        repo,
        &[
            "worktree",
            "add",
            "--detach",
            "-q",
            &work.to_string_lossy(),
            base,
        ],
    );
    for (name, content) in edits {
        let target = work.join(name);
        match content {
            Some(text) => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent).unwrap();
                }
                fs::write(&target, text).unwrap();
            }
            None => {
                let _ = fs::remove_file(&target);
            }
        }
    }
    if executable {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut perms = fs::metadata(work.join(edits[0].0)).unwrap().permissions();
            perms.set_mode(0o755);
            fs::set_permissions(work.join(edits[0].0), perms).unwrap();
        }
    }
    git(&work, &["add", "-A"]);
    let patch = git_raw(&work, &["diff", "--cached", "--binary", "--no-color", base]);
    let patch_path = unique_dir("patch").with_extension("patch");
    fs::write(&patch_path, patch).unwrap();
    git(
        repo,
        &["worktree", "remove", "--force", &work.to_string_lossy()],
    );
    let _ = remove_tree(&work);
    patch_path
}

fn propose(
    repo: &Path,
    agent: &str,
    task: &str,
    base: &str,
    patch: &Path,
    key: &str,
) -> (i32, Json) {
    flow(
        repo,
        &[
            "propose",
            "--agent",
            agent,
            "--task",
            task,
            "--base",
            base,
            "--patch",
            &patch.to_string_lossy(),
            "--key",
            key,
        ],
    )
}

fn assemble(repo: &Path, ids: &[&str]) -> (i32, Json) {
    let mut args: Vec<&str> = vec!["assemble"];
    for id in ids {
        args.push("--proposal");
        args.push(id);
    }
    flow(repo, &args)
}

fn run_candidate(repo: &Path, id: &str) -> (i32, Json) {
    flow(repo, &["run", "--candidate", id])
}

fn publish_candidate(repo: &Path, id: &str, old: &str, extra: &[&str]) -> (i32, Json) {
    let mut args: Vec<&str> = vec!["publish", "--candidate", id, "--expected-old", old];
    args.extend_from_slice(extra);
    flow(repo, &args)
}

fn tree_of(repo: &Path, rev: &str) -> String {
    git(repo, &["rev-parse", &format!("{rev}^{{tree}}")])
}

/// The user's surface: every index entry (path, mode, blob OID) and the bytes of
/// every tracked or untracked file. Flow's own `.flow/` state and `.git/` are
/// excluded by definition — they are expected to change.
///
/// `git status` is deliberately **not** part of the snapshot: after a publication
/// moves the branch, the untouched index is by construction "behind" the new ref,
/// which is the documented behaviour ("publish moves refs only"). What must not
/// change is the index listing and the bytes on disk.
fn snapshot(repo: &Path) -> String {
    let index = git(repo, &["ls-files", "-s"]);
    let mut files: Vec<String> = Vec::new();
    collect(repo, repo, &mut files);
    files.sort();
    let mut out = format!("INDEX\n{index}\n");
    for name in files {
        let path = repo.join(&name);
        let bytes = fs::read(&path).unwrap_or_default();
        out.push_str(&format!("{name} {}\n", hex(&bytes)));
    }
    out
}

fn collect(root: &Path, dir: &Path, out: &mut Vec<String>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = entry.file_name().to_string_lossy().to_string();
        if name == ".git" || (dir == root && name == ".flow") {
            continue;
        }
        if path.is_dir() {
            collect(root, &path, out);
        } else {
            out.push(
                path.strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/"),
            );
        }
    }
}

fn hex(bytes: &[u8]) -> String {
    #[path = "../src/sha256.rs"]
    mod sha256;
    sha256::sha256_hex(bytes)
}

// ------------------------------------------------------------------------- M1
#[test]
fn m1_two_disjoint_agents_publish_exactly_the_verified_tree() {
    let (repo, base) = new_repo();
    let before = snapshot(&repo.path);

    let patch_a = make_patch(
        &repo.path,
        &base,
        &[("alpha.txt", Some("ONE\ntwo\nthree\n"))],
        false,
    );
    let patch_b = make_patch(
        &repo.path,
        &base,
        &[("beta.txt", Some("new file\n"))],
        false,
    );

    let (code, a) = propose(&repo.path, "agent-a", "T1", &base, &patch_a, "k-a1");
    assert_eq!(code, 0, "proposal A: {a}");
    assert_eq!(status_of(&a), "ADMITTED");
    let (code, b) = propose(&repo.path, "agent-b", "T2", &base, &patch_b, "k-b1");
    assert_eq!(code, 0, "proposal B: {b}");
    assert_eq!(status_of(&b), "ADMITTED");

    // Re-submitting the same bytes with the same key is idempotent, and returns
    // the very same proposal — not a new version.
    let (code, again) = propose(&repo.path, "agent-a", "T1", &base, &patch_a, "k-a1");
    assert_eq!(code, 0, "idempotent re-proposal: {again}");
    assert_eq!(field(&again, "proposal_id"), field(&a, "proposal_id"));
    assert_eq!(
        again.get("idempotent").and_then(Json::as_bool),
        Some(true),
        "the CLI must say the admission was a no-op"
    );

    let (code, candidate) = assemble(
        &repo.path,
        &[&field(&a, "proposal_id"), &field(&b, "proposal_id")],
    );
    assert_eq!(code, 0, "assemble: {candidate}");
    assert_eq!(status_of(&candidate), "ASSEMBLED");
    let candidate_id = field(&candidate, "candidate_id");
    let candidate_tree = field(&candidate, "tree_oid");
    assert_ne!(candidate_tree, tree_of(&repo.path, &base));

    let (code, run) = run_candidate(&repo.path, &candidate_id);
    assert_eq!(code, 0, "verified candidate: {run}");
    assert_eq!(status_of(&run), "PASSED");
    assert_eq!(field(&run, "tree_oid"), candidate_tree);
    assert_eq!(field(&run, "candidate_id"), candidate_id);

    let (code, published) = publish_candidate(&repo.path, &candidate_id, &base, &[]);
    assert_eq!(code, 0, "publish: {published}");
    assert_eq!(status_of(&published), "PUBLISHED");
    assert_eq!(field(&published, "tree"), candidate_tree);
    // The tree that was checked is the tree that was published, and the branch
    // really carries it.
    assert_eq!(tree_of(&repo.path, "refs/heads/main"), candidate_tree);
    assert_eq!(field(&published, "old"), base);

    // Flow never touched the user's worktree: alpha.txt is still the base
    // content, beta.txt does not exist, and the snapshot is byte-identical.
    assert_eq!(
        fs::read_to_string(repo.path.join("alpha.txt")).unwrap(),
        "one\ntwo\nthree\n"
    );
    assert!(!repo.path.join("beta.txt").exists());
    assert_eq!(
        snapshot(&repo.path),
        before,
        "Flow must not write the user's files"
    );

    // The published commit is a normal commit on top of the base. `HEAD` follows
    // because the published ref is the checked-out branch: `publish` moves refs
    // only, so the index and worktree are now simply behind — untouched.
    assert_eq!(
        git(&repo.path, &["rev-parse", "HEAD"]),
        field(&published, "commit")
    );
    assert_eq!(git(&repo.path, &["rev-parse", "HEAD^"]), base);
}

// ------------------------------------------------------------------------- M2
#[test]
fn m2_three_agents_collision_is_diagnosed_and_resolved_explicitly() {
    let (repo, base) = new_repo();
    let before = snapshot(&repo.path);

    // A and B both rewrite the same line of shared.txt: a real hunk collision.
    let patch_a = make_patch(
        &repo.path,
        &base,
        &[("shared.txt", Some("red\nGREEN-A\nblue\n"))],
        false,
    );
    let patch_b = make_patch(
        &repo.path,
        &base,
        &[("shared.txt", Some("red\nGREEN-B\nblue\n"))],
        false,
    );
    let patch_c = make_patch(
        &repo.path,
        &base,
        &[("gamma.txt", Some("third agent\n"))],
        false,
    );

    let (_, a) = propose(&repo.path, "agent-a", "T1", &base, &patch_a, "k-a");
    let (_, b) = propose(&repo.path, "agent-b", "T2", &base, &patch_b, "k-b");
    let (_, c) = propose(&repo.path, "agent-c", "T3", &base, &patch_c, "k-c");
    let (ida, idb, idc) = (
        field(&a, "proposal_id"),
        field(&b, "proposal_id"),
        field(&c, "proposal_id"),
    );

    let (code, conflict) = assemble(&repo.path, &[&ida, &idb, &idc]);
    assert_eq!(code, 1, "a collision must not assemble: {conflict}");
    assert_eq!(status_of(&conflict), "REFUSED");
    assert!(
        matches!(
            code_of(&conflict).as_str(),
            "CONFLICT" | "PATH_OPERATION_CONFLICT"
        ),
        "diagnostic code: {conflict}"
    );
    // Nothing moved, and the diagnostic names the failing proposal.
    assert_eq!(git(&repo.path, &["rev-parse", "HEAD"]), base);
    assert_eq!(snapshot(&repo.path), before);
    assert!(
        field(&conflict, "reason").contains(&ida) || field(&conflict, "reason").contains(&idb),
        "diagnostic must name the colliding proposals: {conflict}"
    );

    // Explicit resolution: publish the non-colliding subset, then re-propose on
    // the new base. A and C are disjoint, so they assemble.
    let (code, candidate) = assemble(&repo.path, &[&ida, &idc]);
    assert_eq!(code, 0, "disjoint subset must assemble: {candidate}");
    let cid = field(&candidate, "candidate_id");
    let (code, run) = run_candidate(&repo.path, &cid);
    assert_eq!(code, 0, "subset must verify: {run}");
    let (code, published) = publish_candidate(&repo.path, &cid, &base, &[]);
    assert_eq!(code, 0, "subset must publish: {published}");
    let step_one = git(&repo.path, &["rev-parse", "refs/heads/main"]);
    assert_eq!(
        tree_of(&repo.path, "refs/heads/main"),
        field(&candidate, "tree_oid")
    );

    // Agent B rebases its change explicitly: a new proposal against the new base.
    let patch_b2 = make_patch(
        &repo.path,
        &step_one,
        &[("shared.txt", Some("red\nGREEN-B\nblue\n"))],
        false,
    );
    let (code, b2) = propose(
        &repo.path,
        "agent-b",
        "T2-rebased",
        &step_one,
        &patch_b2,
        "k-b2",
    );
    assert_eq!(code, 0, "rebased proposal: {b2}");
    let (code, candidate2) = assemble(&repo.path, &[&field(&b2, "proposal_id")]);
    assert_eq!(code, 0, "rebased assemble: {candidate2}");
    let (code, run2) = run_candidate(&repo.path, &field(&candidate2, "candidate_id"));
    assert_eq!(code, 0, "rebased candidate verifies: {run2}");
    let (code, published2) = publish_candidate(
        &repo.path,
        &field(&candidate2, "candidate_id"),
        &step_one,
        &[],
    );
    assert_eq!(code, 0, "rebased publish: {published2}");
    // The final tree carries all three changes on a linear history.
    let final_tree = tree_of(&repo.path, "refs/heads/main");
    assert_eq!(final_tree, field(&candidate2, "tree_oid"));
    assert_eq!(
        git(&repo.path, &["show", "refs/heads/main:shared.txt"]),
        "red\nGREEN-B\nblue"
    );
    assert_eq!(
        git(&repo.path, &["show", "refs/heads/main:gamma.txt"]),
        "third agent"
    );
    assert_eq!(
        git(&repo.path, &["show", "refs/heads/main:alpha.txt"]),
        "one\ntwo\nthree"
    );
    assert_eq!(
        snapshot(&repo.path),
        before,
        "no scenario may write the user's files"
    );
}

// ------------------------------------------------------------------------- M3
#[test]
fn m3_stale_base_is_refused_and_a_rebased_proposal_succeeds() {
    let (repo, base) = new_repo();
    let patch = make_patch(&repo.path, &base, &[("delta.txt", Some("delta\n"))], false);
    let (_, proposal) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    let id = field(&proposal, "proposal_id");
    let (_, candidate) = assemble(&repo.path, &[&id]);
    let cid = field(&candidate, "candidate_id");
    let (code, run) = run_candidate(&repo.path, &cid);
    assert_eq!(code, 0, "candidate verifies on its base: {run}");

    // Another writer advances the branch while the candidate is in flight.
    fs::write(repo.path.join("external.txt"), "external\n").unwrap();
    git(&repo.path, &["add", "-A"]);
    git(&repo.path, &["commit", "-q", "-m", "external advance"]);
    let moved = git(&repo.path, &["rev-parse", "HEAD"]);

    let (code, refused) = publish_candidate(&repo.path, &cid, &moved, &[]);
    assert_eq!(code, 1, "a stale base must not publish: {refused}");
    assert_eq!(code_of(&refused), "BASE_MISMATCH");
    assert_eq!(
        git(&repo.path, &["rev-parse", "HEAD"]),
        moved,
        "no forced update"
    );

    // Explicit rebase: new proposal on the new base, new candidate, verified,
    // then published with the matching CAS base.
    let patch2 = make_patch(&repo.path, &moved, &[("delta.txt", Some("delta\n"))], false);
    let (code, proposal2) = propose(&repo.path, "agent-a", "T1-rebased", &moved, &patch2, "k2");
    assert_eq!(code, 0, "rebased proposal: {proposal2}");
    let (code, candidate2) = assemble(&repo.path, &[&field(&proposal2, "proposal_id")]);
    assert_eq!(code, 0, "rebased assemble: {candidate2}");
    let cid2 = field(&candidate2, "candidate_id");
    let (code, run2) = run_candidate(&repo.path, &cid2);
    assert_eq!(code, 0, "rebased candidate verifies: {run2}");
    let (code, published) = publish_candidate(&repo.path, &cid2, &moved, &[]);
    assert_eq!(code, 0, "rebased publish: {published}");
    assert_eq!(
        tree_of(&repo.path, "refs/heads/main"),
        field(&candidate2, "tree_oid")
    );
    // The external advance is still there: the new commit sits on top of it.
    assert_eq!(
        git(&repo.path, &["show", "refs/heads/main:external.txt"]),
        "external"
    );
    assert_eq!(
        git(&repo.path, &["show", "refs/heads/main:delta.txt"]),
        "delta"
    );
}

// ------------------------------------------------------------------- admission
#[test]
fn admission_is_idempotent_and_immutable() {
    let (repo, base) = new_repo();
    let patch = make_patch(&repo.path, &base, &[("x.txt", Some("one\n"))], false);
    let (code, first) = propose(&repo.path, "agent-a", "T1", &base, &patch, "stable-key");
    assert_eq!(code, 0, "{first}");
    let id = field(&first, "proposal_id");

    let (code, again) = propose(&repo.path, "agent-a", "T1", &base, &patch, "stable-key");
    assert_eq!(code, 0);
    assert_eq!(field(&again, "proposal_id"), id);

    // Same key, different content: a correction is a new proposal, not a silent
    // rewrite of an admitted one.
    let other = make_patch(&repo.path, &base, &[("x.txt", Some("two\n"))], false);
    let (code, conflict) = propose(&repo.path, "agent-a", "T1", &base, &other, "stable-key");
    assert_eq!(code, 1, "{conflict}");
    assert_eq!(code_of(&conflict), "IDEMPOTENCY_CONFLICT");
    // The stored tree still reflects the first content.
    let (_, shown) = flow(&repo.path, &["proposals", "show", &id]);
    assert_eq!(status_of(&shown), "ADMITTED");
    assert_eq!(
        field(&shown, "content_digest"),
        field(&first, "content_digest")
    );
}

#[test]
fn proposals_outside_the_trusted_surface_are_refused() {
    let (repo, base) = new_repo();
    let before = snapshot(&repo.path);

    let patch = make_patch(
        &repo.path,
        &base,
        &[(".flow/config.json", Some("pwned\n"))],
        false,
    );
    let (code, out) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    assert_eq!(code, 1, "writing .flow/config.json must be refused: {out}");
    assert!(
        code_of(&out) == "FORBIDDEN_PATH" || code_of(&out) == "PATCH_REFUSED",
        "{out}"
    );

    // A linked worktree cannot hold a `.git` directory, so this patch is crafted
    // by hand. Git itself refuses `.git/` paths; Flow's own check is a second
    // line. Either refusal is a refusal.
    let raw = "diff --git a/.git/config b/.git/config\nnew file mode 100644\nindex 0000000..e69de29\n--- /dev/null\n+++ b/.git/config\n@@ -0,0 +1 @@\n+pwned\n";
    let raw_path = unique_dir("rawpatch").with_extension("patch");
    fs::write(&raw_path, raw).unwrap();
    let (code, out) = propose(&repo.path, "agent-a", "T1", &base, &raw_path, "k2");
    assert_eq!(code, 1, "writing .git/config must be refused: {out}");
    assert!(
        code_of(&out) == "FORBIDDEN_PATH" || code_of(&out) == "PATCH_REFUSED",
        "{out}"
    );
    // An unknown base is refused before anything is written.
    let patch = make_patch(&repo.path, &base, &[("ok.txt", Some("ok\n"))], false);
    let bogus = "0".repeat(40);
    let (code, out) = propose(&repo.path, "agent-a", "T1", &bogus, &patch, "k");
    assert_eq!(code, 1, "{out}");
    assert_eq!(code_of(&out), "BASE_INVALID");
    assert_eq!(snapshot(&repo.path), before);
}

#[test]
fn assembly_reports_order_and_stays_deterministic() {
    let (repo, base) = new_repo();
    let pa = make_patch(&repo.path, &base, &[("a1.txt", Some("a\n"))], false);
    let pb = make_patch(&repo.path, &base, &[("b1.txt", Some("b\n"))], false);
    let (_, a) = propose(&repo.path, "agent-a", "T1", &base, &pa, "ka");
    let (_, b) = propose(&repo.path, "agent-b", "T2", &base, &pb, "kb");
    let (ida, idb) = (field(&a, "proposal_id"), field(&b, "proposal_id"));

    let (code, first) = assemble(&repo.path, &[&ida, &idb]);
    assert_eq!(code, 0, "{first}");
    let (code, second) = assemble(&repo.path, &[&ida, &idb]);
    assert_eq!(code, 0, "{second}");
    assert_eq!(
        field(&first, "candidate_id"),
        field(&second, "candidate_id"),
        "the same ordered input set must yield the same candidate"
    );

    // The order is part of the candidate identity and is reported, not guessed.
    let (code, reversed) = assemble(&repo.path, &[&idb, &ida]);
    assert_eq!(code, 0, "{reversed}");
    assert_ne!(
        field(&reversed, "candidate_id"),
        field(&first, "candidate_id")
    );
    assert_eq!(
        field(&reversed, "tree_oid"),
        field(&first, "tree_oid"),
        "disjoint proposals produce the same tree in either order"
    );
    let (code, dup) = assemble(&repo.path, &[&ida, &ida]);
    assert_eq!(code, 1, "a duplicated proposal is not a set: {dup}");
    assert_eq!(code_of(&dup), "DUPLICATE_PROPOSAL");
    let (code, mismatch) = assemble(&repo.path, &[&ida, "ffffffffffffffffffffffffffffffff"]);
    assert_eq!(code, 1, "{mismatch}");
    assert_eq!(code_of(&mismatch), "UNKNOWN_PROPOSAL");
}

// ------------------------------------------------------------ dry-run / M6
#[test]
fn publish_dry_run_plans_without_mutating_anything() {
    let (repo, base) = new_repo();
    let patch = make_patch(
        &repo.path,
        &base,
        &[("epsilon.txt", Some("epsilon\n"))],
        false,
    );
    let (_, proposal) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    let (_, candidate) = assemble(&repo.path, &[&field(&proposal, "proposal_id")]);
    let cid = field(&candidate, "candidate_id");
    let (code, run) = run_candidate(&repo.path, &cid);
    assert_eq!(code, 0, "{run}");

    let journal_before = fs::read_to_string(repo.path.join(".flow").join("journal.jsonl")).unwrap();
    let refs_before = git(&repo.path, &["for-each-ref"]);
    let before = snapshot(&repo.path);

    let (code, plan) = publish_candidate(&repo.path, &cid, &base, &["--dry-run"]);
    assert_eq!(code, 0, "{plan}");
    assert_eq!(status_of(&plan), "PLAN");
    assert_eq!(plan.get("dry_run").and_then(Json::as_bool), Some(true));
    assert_eq!(field(&plan, "tree"), field(&candidate, "tree_oid"));
    assert_eq!(field(&plan, "old"), base);

    // Nothing happened: same refs, same journal, same files, no new commit.
    assert_eq!(git(&repo.path, &["for-each-ref"]), refs_before);
    assert_eq!(
        fs::read_to_string(repo.path.join(".flow").join("journal.jsonl")).unwrap(),
        journal_before
    );
    assert_eq!(snapshot(&repo.path), before);
    assert_eq!(git(&repo.path, &["rev-parse", "HEAD"]), base);
}

#[test]
fn m6_user_files_and_index_are_preserved_through_the_whole_cycle() {
    let (repo, base) = new_repo();
    // A dirty tracked file, an untracked file and a pre-existing staged change.
    fs::write(repo.path.join("alpha.txt"), "human dirty edit\n").unwrap();
    fs::write(repo.path.join("untracked.txt"), "human untracked\n").unwrap();
    fs::write(repo.path.join("staged.txt"), "staged by the human\n").unwrap();
    git(&repo.path, &["add", "staged.txt"]);
    let before = snapshot(&repo.path);

    let patch = make_patch(&repo.path, &base, &[("zeta.txt", Some("zeta\n"))], false);
    let (code, proposal) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    assert_eq!(code, 0, "{proposal}");
    let (code, candidate) = assemble(&repo.path, &[&field(&proposal, "proposal_id")]);
    assert_eq!(code, 0, "{candidate}");
    let cid = field(&candidate, "candidate_id");
    let (code, run) = run_candidate(&repo.path, &cid);
    assert_eq!(code, 0, "{run}");
    let (code, published) = publish_candidate(&repo.path, &cid, &base, &[]);
    assert_eq!(code, 0, "{published}");

    assert_eq!(
        snapshot(&repo.path),
        before,
        "propose/assemble/run/publish must not change one byte of the user's worktree or index"
    );
    assert_eq!(
        fs::read_to_string(repo.path.join("alpha.txt")).unwrap(),
        "human dirty edit\n"
    );
    // The staged change is still staged exactly as the human left it (compared
    // with the base, because the published ref moved and HEAD now follows it).
    assert_eq!(
        git(&repo.path, &["diff", "--cached", "--name-only", &base]),
        "staged.txt"
    );
    assert_eq!(
        git(&repo.path, &["diff", "--name-only"]),
        "alpha.txt",
        "the only unstaged change is the human's own dirty edit"
    );
}

#[test]
fn publishing_a_candidate_requires_a_verified_receipt() {
    let (repo, base) = new_repo();
    let patch = make_patch(&repo.path, &base, &[("eta.txt", Some("eta\n"))], false);
    let (_, proposal) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    let (_, candidate) = assemble(&repo.path, &[&field(&proposal, "proposal_id")]);
    let cid = field(&candidate, "candidate_id");

    let (code, refused) = publish_candidate(&repo.path, &cid, &base, &[]);
    assert_eq!(
        code, 1,
        "an unverified candidate must not publish: {refused}"
    );
    assert_eq!(code_of(&refused), "NO_RECEIPT");
    assert_eq!(git(&repo.path, &["rev-parse", "HEAD"]), base);

    let (code, unknown) = run_candidate(&repo.path, "0123456789abcdef0123456789abcdef");
    assert_eq!(code, 1, "{unknown}");
    assert_eq!(code_of(&unknown), "UNKNOWN_CANDIDATE");
}

#[test]
fn binary_and_mode_changes_survive_the_cycle() {
    let (repo, base) = new_repo();
    // A NUL byte makes this a binary blob for Git.
    let work = unique_dir("bin");
    fs::create_dir_all(&work).unwrap();
    git(
        &repo.path,
        &[
            "worktree",
            "add",
            "--detach",
            "-q",
            &work.to_string_lossy(),
            &base,
        ],
    );
    fs::write(work.join("blob.bin"), b"\x00\x01\x02\xffBINARY\x00").unwrap();
    fs::write(work.join("script.sh"), "#!/bin/sh\necho hi\n").unwrap();
    git(&work, &["add", "-A"]);
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(work.join("script.sh")).unwrap().permissions();
        perms.set_mode(0o755);
        fs::set_permissions(work.join("script.sh"), perms).unwrap();
        git(&work, &["add", "-A"]);
    }
    let patch_text = git_raw(
        &work,
        &["diff", "--cached", "--binary", "--no-color", &base],
    );
    git(
        &repo.path,
        &["worktree", "remove", "--force", &work.to_string_lossy()],
    );
    let _ = remove_tree(&work);
    let patch = unique_dir("binpatch").with_extension("patch");
    fs::write(&patch, patch_text).unwrap();

    let (code, proposal) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    assert_eq!(code, 0, "binary/mode proposal: {proposal}");
    let (code, candidate) = assemble(&repo.path, &[&field(&proposal, "proposal_id")]);
    assert_eq!(code, 0, "binary/mode assemble: {candidate}");
    let cid = field(&candidate, "candidate_id");
    let (code, run) = run_candidate(&repo.path, &cid);
    assert_eq!(code, 0, "binary/mode verify: {run}");
    let (code, published) = publish_candidate(&repo.path, &cid, &base, &[]);
    assert_eq!(code, 0, "binary/mode publish: {published}");

    let blob = git(
        &repo.path,
        &["cat-file", "blob", "refs/heads/main:blob.bin"],
    );
    let _ = blob;
    let listing = git(&repo.path, &["ls-tree", "-r", "refs/heads/main"]);
    assert!(
        listing.contains("100644 blob") && listing.contains("blob.bin"),
        "binary entry must be a regular file: {listing}"
    );
    #[cfg(unix)]
    assert!(
        listing.contains("100755 blob") && listing.contains("script.sh"),
        "the executable bit must be preserved: {listing}"
    );
    // The published blob is byte-identical to what the agent proposed.
    let out = Command::new("git")
        .arg("-C")
        .arg(&repo.path)
        .args(["cat-file", "blob", "refs/heads/main:blob.bin"])
        .output()
        .unwrap();
    assert_eq!(out.stdout, b"\x00\x01\x02\xffBINARY\x00");
}

// ----------------------------------------------------------------- M7 - M10
/// An agent can be replaced: re-submitting the same immutable proposal with the
/// same key is a no-op, the attribution stays with the original proposal, and the
/// work continues without a second admission.
#[test]
fn m7_a_replacement_agent_resumes_from_the_immutable_artefacts() {
    let (repo, base) = new_repo();
    let patch = make_patch(
        &repo.path,
        &base,
        &[("handover.txt", Some("done by A\n"))],
        false,
    );
    let (code, first) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k-a");
    assert_eq!(code, 0, "{first}");
    let id = field(&first, "proposal_id");
    let (code, candidate) = assemble(&repo.path, &[&id]);
    assert_eq!(code, 0, "{candidate}");
    let cid = field(&candidate, "candidate_id");

    // The replacement agent does not know the previous conversation: it reads the
    // candidate, re-runs the verification and re-submits the same bytes.
    let (code, explain) = flow(&repo.path, &["explain", "--candidate", &cid]);
    assert_eq!(code, 0, "{explain}");
    let proposals = explain.get("proposals").and_then(Json::as_arr).unwrap();
    assert_eq!(proposals.len(), 1);
    assert_eq!(
        proposals[0].get("agent_id").and_then(Json::as_str),
        Some("agent-a"),
        "attribution must survive the handover: {explain}"
    );

    // The idempotency slot belongs to an actor: a replacement agent with the same
    // key gets its own proposal id (it is a different author), and the original
    // proposal is untouched. Nothing is merged silently.
    let (code, again) = propose(&repo.path, "agent-b", "T1", &base, &patch, "k-a");
    assert_eq!(code, 0, "a new actor admits its own proposal: {again}");
    assert_ne!(
        field(&again, "proposal_id"),
        id,
        "a different agent must not be folded into another agent's proposal"
    );
    assert_eq!(field(&again, "agent_id"), "agent-b");
    let (_, reloaded) = flow(&repo.path, &["proposals", "show", &id]);
    assert_eq!(field(&reloaded, "agent_id"), "agent-a");
    assert_eq!(
        field(&reloaded, "content_digest"),
        field(&first, "content_digest")
    );

    let (code, run) = run_candidate(&repo.path, &cid);
    assert_eq!(code, 0, "{run}");
    let (code, published) = publish_candidate(&repo.path, &cid, &base, &[]);
    assert_eq!(code, 0, "{published}");
    assert_eq!(
        tree_of(&repo.path, "refs/heads/main"),
        field(&candidate, "tree_oid")
    );
    // The attribution is still visible after publication.
    let (code, explain) = flow(&repo.path, &["explain", "--candidate", &cid]);
    assert_eq!(code, 0, "{explain}");
    let proposals = explain.get("proposals").and_then(Json::as_arr).unwrap();
    assert_eq!(
        proposals[0].get("agent_id").and_then(Json::as_str),
        Some("agent-a")
    );
}

/// Two proposals built on different bases cannot be assembled: that is the
/// dependency refusal (a candidate may not silently rebase somebody's work).
#[test]
fn m8_proposals_on_different_bases_are_refused_with_both_bases() {
    let (repo, base) = new_repo();
    let pa = make_patch(&repo.path, &base, &[("one.txt", Some("1\n"))], false);
    let (_, a) = propose(&repo.path, "agent-a", "T1", &base, &pa, "ka");
    // advance the branch and build a second proposal on the new base
    fs::write(repo.path.join("external.txt"), "x\n").unwrap();
    git(&repo.path, &["add", "-A"]);
    git(&repo.path, &["commit", "-q", "-m", "advance"]);
    let moved = git(&repo.path, &["rev-parse", "HEAD"]);
    let pb = make_patch(&repo.path, &moved, &[("two.txt", Some("2\n"))], false);
    let (_, b) = propose(&repo.path, "agent-b", "T2", &moved, &pb, "kb");
    let (code, out) = assemble(
        &repo.path,
        &[&field(&a, "proposal_id"), &field(&b, "proposal_id")],
    );
    assert_eq!(code, 1, "{out}");
    assert_eq!(code_of(&out), "BASE_MISMATCH");
    let reason = field(&out, "reason");
    assert!(
        reason.contains(&base) && reason.contains(&moved),
        "{reason}"
    );
}

/// A cloned repository with a hostile policy executes nothing before approval,
/// and its symlinked state cannot be written through after approval either.
#[test]
fn m9_a_hostile_cloned_repository_cannot_execute_or_escape() {
    let (repo, base) = new_repo();
    // Simulate a clone: the policy arrives with the repository, unapproved.
    let canary = unique_dir("canary");
    let canary_path = format!("{}", canary.to_string_lossy()).replace('\\', "/");
    write_config_unapproved(
        &repo.path,
        &format!(
            r#"{{"id":"hostile","program":"python","args":["-c","open(r'{canary_path}','w').write('executed')"],"required":true,"timeout_s":30}}"#
        ),
    );
    let outside = unique_dir("outside");
    fs::write(&outside, "outside\n").unwrap();
    let journal = repo.path.join(".flow").join("journal.jsonl");
    let _ = fs::remove_file(&journal);

    let (code, out) = flow(&repo.path, &["run"]);
    assert_eq!(code, 1, "an unapproved policy must not run: {out}");
    assert_eq!(code_of(&out), "POLICY_NOT_APPROVED");
    assert!(
        !canary.exists(),
        "the hostile program must not have executed"
    );

    let (code, approved) = flow(&repo.path, &["approve"]);
    assert_eq!(code, 0, "{approved}");
    assert!(
        approved
            .get("obligations")
            .and_then(Json::as_arr)
            .map(|a| !a.is_empty())
            .unwrap_or(false),
        "approval must show exactly what will run: {approved}"
    );
    // Even approved, the state paths cannot be turned into an escape hatch.
    #[cfg(unix)]
    {
        std::os::unix::fs::symlink(&outside, &journal).unwrap();
        let (code, run) = flow(&repo.path, &["run"]);
        assert!(code == 0 || code == 1, "{run}");
        let (code, published) = flow(&repo.path, &["publish"]);
        assert_eq!(
            code, 1,
            "a symlinked journal must not be published through: {published}"
        );
        assert_eq!(fs::read_to_string(&outside).unwrap(), "outside\n");
    }
    let _ = base;
}

/// A record from another schema is refused, never reinterpreted.
#[test]
fn m10_a_record_from_another_schema_is_refused() {
    let (repo, base) = new_repo();
    let patch = make_patch(&repo.path, &base, &[("x.txt", Some("x\n"))], false);
    let (_, proposal) = propose(&repo.path, "agent-a", "T1", &base, &patch, "k");
    let id = field(&proposal, "proposal_id");
    let path = repo
        .path
        .join(".flow")
        .join("proposals")
        .join(format!("{id}.json"));
    let mut value = json::parse(&fs::read_to_string(&path).unwrap()).unwrap();
    if let Json::Obj(pairs) = &mut value {
        for (k, v) in pairs.iter_mut() {
            if k == "schema" {
                *v = Json::str("flow-proposal/0");
            }
        }
    }
    fs::write(&path, value.to_string_pretty()).unwrap();
    let (code, out) = flow(&repo.path, &["proposals", "show", &id]);
    assert_eq!(code, 1, "a future/foreign schema must be refused: {out}");
    let text = out.to_string();
    assert!(text.contains("flow-proposal/0"), "{text}");
    assert!(text.contains("refusing to reinterpret"), "{text}");
}
